async def show_review(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    d = context.user_data
    details = []
    if d.get('partner'): details.append('партнёр: да')
    if d.get('children'): details.append('дети: да')
    if d.get('parents'): details.append('родители: да')
    text = (
        "Пожалуйста, проверьте сведения перед созданием документа:\n\n"
        f"ФИО: {d['full_name']}\nДата рождения: {d['dob_str']}\nМетодика: {d['method']}\n"
        f"Время рождения: {d.get('birth_time', 'не указано')}\nМесто рождения: {d.get('birth_place', 'не указано')}\n"
        f"Дополнительные разделы: {', '.join(details) if details else 'не добавлены'}\n\n"
        "Для подготовки текста ваши данные будут переданы сервису GigaChat (Сбер).\n\nВсё верно?"
    )
    markup = kb([[('✅ Да, создать разбор', 'confirm_yes')], [('↩️ Начать заново', 'confirm_restart')]])
    if update.callback_query:
        await update.callback_query.message.reply_text(text, reply_markup=markup)
    else:
        await update.message.reply_text(text, reply_markup=markup)


async def confirm(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    q = update.callback_query
    await q.answer()
    if q.data == 'confirm_restart':
        context.user_data.clear()
        await q.edit_message_text("Начнём заново. Введите полное ФИО (имя, отчество, фамилия).")
        return NAME
    await q.edit_message_text("✨ Спасибо за подтверждение! Подготавливаю ваш подробный документ. Это может занять несколько минут…")
    path = None
    try:
        path = await build_report(context.user_data)
        with open(path, 'rb') as f:
            await context.bot.send_document(
                chat_id=q.from_user.id, document=f, filename=Path(path).name,
                caption=f"Ваш разбор готов, {context.user_data['first_name']}! Спасибо, что выбрали нас — мы ценим ваше доверие."
            )
        await context.bot.send_message(
            q.from_user.id,
            f"💛 {context.user_data['first_name']}, спасибо, что выбрали нас. Мы ценим ваше доверие и надеемся, что разбор станет полезным поводом для размышлений.\n\nЧтобы начать заново, нажмите «🔄 Старт».",
            reply_markup=PANEL,
        )
    except Exception:
        log.exception("Report generation or document delivery failed")
        await context.bot.send_message(q.from_user.id, "Не получилось сформировать или отправить документ. Попробуйте ещё раз через «🔄 Старт». Если ошибка повторится, администратору нужно проверить Railway Logs.", reply_markup=PANEL)
    finally:
        if path and os.path.exists(path):
            os.remove(path)
        context.user_data.clear()
    return ConversationHandler.END


async def panel_action(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    if update.message.text.strip() == "🔄 Старт":
        return await start(update, context)
    return await cancel(update, context)


async def cancel(update: Update, context: ContextTypes.DEFAULT_TYPE) -> int:
    context.user_data.clear()
    await update.message.reply_text("Разбор отменён. Нажмите «🔄 Старт», чтобы начать заново.", reply_markup=PANEL)
    return ConversationHandler.END


